create table if not exists public.pompkin_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),recipient_name text not null,customer_mobile text,full_address text not null,subtotal numeric(10,2) not null,shipping_fee numeric(10,2),coffee_amount numeric(10,2) not null default 0,total numeric(10,2),status text not null default 'pending' check(status in('pending','accepted','paid','completed')),payment_status text not null default 'unpaid' check(payment_status in('unpaid','submitted','paid')),tracking_number text,tracking_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.pompkin_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.pompkin_orders(id) on delete cascade,product_id text not null references public.pompkin_products(id),product_name text not null,unit_price numeric(10,2) not null,quantity integer not null check(quantity>0),subtotal numeric(10,2) not null);
alter table public.pompkin_orders enable row level security; alter table public.pompkin_order_items enable row level security;
create policy orders_customer on public.pompkin_orders for select using(auth.uid()=user_id or public.is_pompkin_admin()); create policy orders_insert on public.pompkin_orders for insert with check(auth.uid()=user_id); create policy orders_admin_update on public.pompkin_orders for update using(public.is_pompkin_admin()) with check(public.is_pompkin_admin());
create policy items_customer on public.pompkin_order_items for select using(exists(select 1 from public.pompkin_orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_pompkin_admin()))); create policy items_insert on public.pompkin_order_items for insert with check(exists(select 1 from public.pompkin_orders o where o.id=order_id and o.user_id=auth.uid())); create policy items_admin on public.pompkin_order_items for all using(public.is_pompkin_admin()) with check(public.is_pompkin_admin());
